/**
 * Homepage media manifest: the hero layers and the closing CTA. Mood and
 * destination images live with their content in features/discover/data.ts.
 *
 * All current assets are ORIGINAL ARTWORK generated by
 * apps/web/scripts/generate-artwork.mjs (no third-party images, no licence
 * obligations). They are stand-ins for licensed photography: to replace a slot,
 * add the optimised file under apps/web/public/media/photos/, point `src` (and
 * `portraitSrc` where present) at it, update `alt`, set `kind: 'photo'` and
 * record the source/licence in `credit`. See docs/media-assets.md.
 */

export interface MediaAsset {
  /** Landscape / default file, served from apps/web/public. */
  src: string;
  /** Art-directed portrait crop for phones (< 768px). */
  portraitSrc?: string;
  /** Describes the scene. "" marks the image as decorative. */
  alt: string;
  /** object-position for responsive cropping, e.g. "62% 50%". */
  focalPoint?: string;
  /** Fallback colour shown while loading (matches the artwork's dominant tone). */
  tone: string;
  kind: 'artwork' | 'photo';
  /** Required for photos: source and licence. */
  credit?: string;
}

const ART = '/media/artwork';

